def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    import numpy as np

    # Parse the grid values into a 2D array
    grid = np.zeros((N, N), dtype=int)
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1, y-1] = value

    # Initialize the DP table
    dp = np.zeros((2, N, N), dtype=int)

    # Fill the DP table
    for i in range(2):
        for x in range(N):
            for y in range(N):
                if x == 0 and y == 0:
                    continue
                if i == 0:
                    dp[i, x, y] = dp[i, x-1, y] + grid[x, y]
                else:
                    dp[i, x, y] = max(dp[i-1, x-1, y], dp[i-1, x, y-1]) + grid[x, y]

    # The result is the maximum of the last two states
    return max(dp[0, N-1, N-1], dp[1, N-1, N-1])

