def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Find the peak position
    peak = 0
    for i in range(1, n):
        if heights[i] > heights[peak]:
            peak = i

    # Calculate the number of students to remove before the peak
    left_to_remove = 0
    for i in range(peak):
        if heights[i] > heights[i + 1]:
            left_to_remove += 1

    # Calculate the number of students to remove after the peak
    right_to_remove = 0
    for i in range(peak, n - 1):
        if heights[i] < heights[i + 1]:
            right_to_remove += 1

    return left_to_remove + right_to_remove

